package io.baozhu.copilot.service; import com.fasterxml.jackson.databind.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; @Repository public class CopilotRequestRepository { private final JdbcTemplate jdbc; private final ObjectMapper mapper; public CopilotRequestRepository(JdbcTemplate j,ObjectMapper m){jdbc=j;mapper=m;} public void save(String t,String p,String input,Object output){try{jdbc.update("INSERT INTO copilot_request(request_type,provider,input_summary,output_json) VALUES (?,?,?,?)",t,p,input,mapper.writeValueAsString(output));}catch(Exception e){throw new IllegalStateException("Could not persist copilot audit record",e);}} }